class Solution {
public:
    vector<int> cheapestJump(vector<int>& coins, int maxJump) {
        int n = coins.size();
        if (coins.back() == -1 || coins[0] == -1) return {};

        vector<long long> cost(n, 1e18);
        vector<int> nxt(n, -1);
        cost[n - 1] = coins[n - 1];

        for (int i = n - 2; i >= 0; i--) {
            if (coins[i] == -1) continue;
            for (int j = i + 1; j <= min(n - 1, i + maxJump); j++) {
                if (cost[j] < 1e18) {
                    long long total = coins[i] + cost[j];
                    if (total < cost[i]) {
                        cost[i] = total;
                        nxt[i] = j;
                    }
                }
            }
        }

        if (cost[0] >= 1e18) return {};

        vector<int> path;
        int curr = 0;
        while (curr != -1) {
            path.push_back(curr + 1);
            curr = nxt[curr];
        }
        return path;
    }
};

class Solution {
    public List<Integer> cheapestJump(int[] coins, int maxJump) {
        int n = coins.length;
        if (coins[n - 1] == -1 || coins[0] == -1) return Collections.emptyList();

        long[] cost = new long[n];
        Arrays.fill(cost, Long.MAX_VALUE);
        int[] nxt = new int[n];
        Arrays.fill(nxt, -1);
        cost[n - 1] = coins[n - 1];

        for (int i = n - 2; i >= 0; i--) {
            if (coins[i] == -1) continue;
            for (int j = i + 1; j <= Math.min(n - 1, i + maxJump); j++) {
                if (cost[j] != Long.MAX_VALUE) {
                    long total = coins[i] + cost[j];
                    if (total < cost[i]) {
                        cost[i] = total;
                        nxt[i] = j;
                    }
                }
            }
        }

        if (cost[0] == Long.MAX_VALUE) return Collections.emptyList();

        List<Integer> path = new ArrayList<>();
        int curr = 0;
        while (curr != -1) {
            path.add(curr + 1);
            curr = nxt[curr];
        }
        return path;
    }
}

var cheapestJump = function(coins, maxJump) {
    const n = coins.length;
    if (coins[n - 1] === -1 || coins[0] === -1) return [];

    const cost = Array(n).fill(Infinity);
    const nxt = Array(n).fill(-1);
    cost[n - 1] = coins[n - 1];

    for (let i = n - 2; i >= 0; i--) {
        if (coins[i] === -1) continue;
        const limit = Math.min(n - 1, i + maxJump);
        for (let j = i + 1; j <= limit; j++) {
            if (cost[j] !== Infinity) {
                const total = coins[i] + cost[j];
                if (total < cost[i]) {
                    cost[i] = total;
                    nxt[i] = j;
                }
            }
        }
    }

    if (cost[0] === Infinity) return [];

    const path = [];
    let curr = 0;
    while (curr !== -1) {
        path.push(curr + 1);
        curr = nxt[curr];
    }
    return path;
};
